param([string]$RepoRoot=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path,[string]$Python=(Join-Path (Resolve-Path (Join-Path $PSScriptRoot '..')).Path 'papers\TransVisDrone\.venv\Scripts\python.exe'),[string]$RunId='nps_vatd_cuda_rank_v1',[string]$OutputRoot=(Join-Path (Resolve-Path (Join-Path $PSScriptRoot '..')).Path 'artifacts\nps_sota_research\nps_vatd_cuda_rank_v1_runner'))
$ErrorActionPreference='Stop';Set-Location $RepoRoot
$orchestrator=Join-Path $RepoRoot 'tools\run_nps_vatd_cuda_rank.py';if(-not(Test-Path $Python -PathType Leaf)){throw "Python not found: $Python"};if(-not(Test-Path $orchestrator -PathType Leaf)){throw "Orchestrator not found: $orchestrator"}
New-Item -ItemType Directory -Force -Path $OutputRoot,(Join-Path $OutputRoot 'logs')|Out-Null;$pidFile=Join-Path $OutputRoot "$RunId.pid";if(Test-Path $pidFile){$oldPid=Get-Content $pidFile|Select-Object -First 1;$old=Get-Process -Id $oldPid -ErrorAction SilentlyContinue;if($old){Write-Host "already running pid=$oldPid";exit 0}}
$ts=Get-Date -Format 'yyyyMMdd_HHmmss';$stdout=Join-Path $OutputRoot ('logs\'+$RunId+'_'+$ts+'.out.txt');$stderr=Join-Path $OutputRoot ('logs\'+$RunId+'_'+$ts+'.err.txt');$progress=Join-Path $OutputRoot 'progress.json'
$process=Start-Process -FilePath $Python -ArgumentList @($orchestrator) -WorkingDirectory $RepoRoot -RedirectStandardOutput $stdout -RedirectStandardError $stderr -WindowStyle Hidden -PassThru
Set-Content -LiteralPath $pidFile -Value $process.Id;@("pid=$($process.Id)","started=$(Get-Date -Format o)","stdout=$stdout","stderr=$stderr","progress=$progress")|Set-Content -LiteralPath (Join-Path $OutputRoot "$RunId.meta.txt");Write-Host "started pid=$($process.Id) stdout=$stdout stderr=$stderr"
